<!doctype html><html><head><meta charset="utf-8"><title>Attendance Report</title><style>body{font-family:DejaVu Sans,sans-serif;font-size:10px;color:#111}h2{margin-bottom:3px}.meta{color:#555;margin-bottom:15px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ccc;padding:6px;text-align:left}th{background:#eee}.badge{text-transform:capitalize}@media print{button{display:none}}</style></head><body>@isset($print)<button onclick="window.print()">Print</button>@endisset<h2>Attendance Report</h2><div class="meta">Generated {{now()->format('d M Y H:i')}} · Filters: {{collect($filters)->filter(fn($v)=>$v!==null&&$v!=='')->map(fn($v,$k)=>str_replace('_',' ',ucwords($k,'_')).': '.$v)->implode(' · ')?:'All records'}}</div><table><thead><tr><th>Date</th><th>User</th><th>Status</th><th>In</th><th>Out</th><th>Hours</th><th>Leave</th><th>Remarks</th></tr></thead><tbody>@foreach($records as $a)<tr><td>{{$a->attendance_date->format('Y-m-d')}}</td><td>{{$a->user->name}}<br>{{$a->user->email}}</td><td>{{ucwords(str_replace('_',' ',$a->status))}}</td><td>{{$a->check_in}}</td><td>{{$a->check_out}}</td><td>{{sprintf('%d:%02d',intdiv($a->working_minutes,60),$a->working_minutes%60)}}</td><td>{{$a->leaveRequest?->leave_type}}</td><td>{{$a->remarks}}</td></tr>@endforeach</tbody></table>@isset($print)<script>window.onload=()=>window.print()</script>@endisset</body></html>
